pred_sql:
SELECT s.School, s.MailZip
FROM schools s
WHERE s.AdmFName1 = 'Avetik' AND s.AdmLName1 = 'Atoian';

SELECT DISTINCT layout
FROM cards
WHERE keywords LIKE '%Flying%';

SELECT availability 
FROM cards 
WHERE artist = 'Daren Bader';

SELECT setCode
FROM sets
WHERE type = 'expansion';

SELECT subtypes, supertypes 
FROM cards 
WHERE name = 'Molimo, Maro-Sorcerer';

SELECT artist
FROM cards
WHERE flavorName = 'Battra, Dark Destroyer';

SELECT COUNT(*) 
FROM Player 
WHERE player_name LIKE 'Aaron%' AND birthday > '1990';

SELECT SUM(wins) AS total_victories
FROM driverStandings
WHERE points = 91;

SELECT 
    (SELECT COUNT(*) FROM superhero AS s JOIN publisher AS p ON s.publisher_id = p.id WHERE p.publisher_name = 'Marvel Comics') -
    (SELECT COUNT(*) FROM superhero AS s JOIN publisher AS p ON s.publisher_id = p.id WHERE p.publisher_name = 'DC Comics') AS difference;

SELECT CAST(SUM(CASE WHEN UA <= 6.5 THEN 1 ELSE 0 END) AS REAL) * 100 / COUNT(*) 
FROM Laboratory 
WHERE `U-PRO` > 0 AND `U-PRO` < 30;

SELECT CAST(SUM(CASE WHEN element = 'h' THEN 1 ELSE 0 END) AS REAL) * 100 / COUNT(atom_id) AS percent
FROM atom
WHERE molecule_id = 'TR206';
